/**
 * Business layer — spending summary generation. Turns a period's insights aggregation into a
 * short natural-language recap, generated by Claude Haiku 4.5 via the `generate-spending-summary`
 * Supabase Edge Function (src/data/spending-summary.data.ts) — the Anthropic API key never ships
 * in the mobile bundle.
 */

import { requestSpendingSummary } from '@/data/spending-summary.data';
import type { CategoryTotal } from '@/services/insights.service';

export type SpendingSummaryInput = {
  /** Human-readable period, e.g. "This week", "November 2026". */
  periodLabel: string;
  spent: number;
  saved: number;
  goal: number;
  onTrack: boolean;
  /** Highest-first category totals for the period; may be empty. */
  breakdown: CategoryTotal[];
};

export type SpendingSummary = {
  text: string;
};

export async function generateSpendingSummary(
  input: SpendingSummaryInput
): Promise<SpendingSummary> {
  return requestSpendingSummary(input);
}
